import string

def generate_random_string(max_length=100):
    length = random.randint(0, max_length)
    return ''.join(random.choices(string.printable, k=length))

def generate_random_json():
    return {
        'string': generate_random_string(),
        'number': random.uniform(-1e10, 1e10),
        'integer': random.randint(-1000000, 1000000),
        'boolean': random.choice([True, False]),
        'null': None,
        'array': [random.randint(0, 100) for _ in range(random.randint(0, 10))]
    }

def fuzz_function(func, iterations=1000):
    errors = []
    for i in range(iterations):
        try:
            input_data = generate_random_json()
            func(input_data)
        except Exception as e:
            errors.append((i, input_data, str(e)))

    print(f"Tested {iterations} inputs")
    print(f"Errors: {len(errors)}")
    return errors

def my_function(data):
    return data['string'].upper()

fuzz_function(my_function)"}

