✿ARGS✿: {"path": "./pubsub.py", "content": "from collections import defaultdict

class PubSub:
    def __init__(self):
        self.subscribers = defaultdict(list)

    def subscribe(self, event, callback):
        self.subscribers[event].append(callback)

    def unsubscribe(self, event, callback):
        self.subscribers[event].remove(callback)

    def publish(self, event, data=None):
        for callback in self.subscribers[event]:
            callback(data)

def on_user_created(user):
    print(f"User created: {user}")

def send_welcome_email(user):
    print(f"Sending welcome email to {user}")

pubsub = PubSub()
pubsub.subscribe('user.created', on_user_created)
pubsub.subscribe('user.created', send_welcome_email)
pubsub.publish('user.created', {'name': 'Alice', 'email': 'alice@example.com'})"}

