from pathlib import Path

def sync_folders(source, dest, delete=False):
    source, dest = Path(source), Path(dest)
    dest.mkdir(parents=True, exist_ok=True)

    for src_file in source.rglob('*'):
        if src_file.is_file():
            rel = src_file.relative_to(source)
            dst = dest / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            if not dst.exists() or src_file.stat().st_mtime > dst.stat().st_mtime:
                shutil.copy2(src_file, dst)
                print(f"Copied: {rel}")

    if delete:
        for dst_file in dest.rglob('*'):
            if dst_file.is_file():
                if not (source / dst_file.relative_to(dest)).exists():
                    dst_file.unlink()

sync_folders('./source', './backup')"}

