✿ARGS✿: {"path": "./metrics.py", "content": "import time
from functools import wraps

class Metrics:
    def __init__(self):
        self.counters = {}
        self.gauges = {}
        self.timers = {}

    def increment(self, name, value=1):
        self.counters[name] = self.counters.get(name, 0) + value

    def gauge(self, name, value):
        self.gauges[name] = value

    def timer(self, name):
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                start = time.time()
                result = func(*args, **kwargs)
                elapsed = time.time() - start
                if name not in self.timers:
                    self.timers[name] = []
                self.timers[name].append(elapsed)
                return result
            return wrapper
        return decorator

    def report(self):
        print("Counters:", self.counters)
        print("Gauges:", self.gauges)
        for name, times in self.timers.items():
            avg = sum(times) / len(times)
            print(f"Timer {name}: avg={avg:.3f}s, count={len(times)}")

metrics = Metrics()

@metrics.timer('process_data')
def process_data():
    time.sleep(0.1)
    metrics.increment('processed_items')

for _ in range(5):
    process_data()
metrics.report()"}

