def load_snapshot(name, snapshots_dir='snapshots'):
    path = os.path.join(snapshots_dir, f"{name}.json")
    if not os.path.exists(path):
        return None
    with open(path) as f:
        return json.load(f)

def assert_matches_snapshot(name, actual, update=False):
    expected = load_snapshot(name)

    if expected is None or update:
        save_snapshot(name, actual)
        return True

    assert actual == expected, f"Snapshot mismatch for {name}"
    return True

