✿ARGS✿: {"path": "./template_engine.py", "content": "import re

def render_template(template, context):
    def replace_var(match):
        var_name = match.group(1).strip()
        parts = var_name.split('.')
        value = context
        for part in parts:
            if isinstance(value, dict):
                value = value.get(part, '')
            else:
                value = getattr(value, part, '')
        return str(value)

    result = re.sub(r'\{\{\s*(.+?)\s*\}\}', replace_var, template)
    return result

def render_file(template_file, output_file, context):
    with open(template_file) as f:
        template = f.read()

    result = render_template(template, context)

    with open(output_file, 'w') as f:
        f.write(result)

    return result

template = "Hello, {{ user.name }}! Your email is {{ user.email }}."
context = {'user': {'name': 'Alice', 'email': 'alice@example.com'}}
print(render_template(template, context))"}

