✿ARGS✿: {"path": "./simple_orm.py", "content": "import sqlite3

class Field:
    def __init__(self, field_type, primary_key=False, nullable=True):
        self.field_type = field_type
        self.primary_key = primary_key
        self.nullable = nullable

class Model:
    _connection = None

    @classmethod
    def set_connection(cls, db_path):
        cls._connection = sqlite3.connect(db_path)
        cls._connection.row_factory = sqlite3.Row

    @classmethod
    def create_table(cls):
        fields = []
        for name, field in cls.__dict__.items():
            if isinstance(field, Field):
                sql = f"{name} {field.field_type}"
                if field.primary_key:
                    sql += " PRIMARY KEY"
                if not field.nullable:
                    sql += " NOT NULL"
                fields.append(sql)

        sql = f"CREATE TABLE IF NOT EXISTS {cls.__name__.lower()} ({', '.join(fields)})"
        cls._connection.execute(sql)
        cls._connection.commit()

    def save(self):
        table = self.__class__.__name__.lower()
        data = {k: v for k, v in self.__dict__.items() if not k.startswith('_')}
        columns = ', '.join(data.keys())
        placeholders = ', '.join('?' * len(data))
        sql = f"INSERT INTO {table} ({columns}) VALUES ({placeholders})"
        cls._connection.execute(sql, list(data.values()))
        cls._connection.commit()

class User(Model):
    id = Field('INTEGER', primary_key=True)
    name = Field('TEXT', nullable=False)
    email = Field('TEXT')"}

