import time
import os
import subprocess

def watch_and_run(path, command, interval=1):
    last_mtime = 0
    print(f"Watching {path} - Press Ctrl+C to stop")

    while True:
        try:
            mtime = os.path.getmtime(path)
            if mtime > last_mtime:
                last_mtime = mtime
                print(f"\n{'='*50}")
                print(f"File changed, running: {command}")
                print('='*50)
                subprocess.run(command, shell=True)
            time.sleep(interval)
        except KeyboardInterrupt:
            print("\nStopped")
            break
        except FileNotFoundError:
            print(f"File not found: {path}")
            time.sleep(interval)

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print("Usage: python file_watcher.py <file> <command>")
        sys.exit(1)
    watch_and_run(sys.argv[1], sys.argv[2])"}

