def aggregate_logs(log_dir, pattern='*.log'):
    errors = Counter()
    warnings = Counter()

    for log_file in Path(log_dir).glob(pattern):
        with open(log_file) as f:
            for line in f:
                if 'ERROR' in line:
                    msg = re.sub(r'\d+', 'N', line.strip())
                    errors[msg] += 1
                elif 'WARNING' in line:
                    msg = re.sub(r'\d+', 'N', line.strip())
                    warnings[msg] += 1

