class Model:
    _table = None
    _db = None

    @classmethod
    def set_db(cls, db_path):
        cls._db = sqlite3.connect(db_path)
        cls._db.row_factory = sqlite3.Row

    @classmethod
    def find(cls, id):
        cursor = cls._db.execute(f"SELECT * FROM {cls._table} WHERE id = ?", (id,))
        row = cursor.fetchone()
        return dict(row) if row else None

    @classmethod
    def all(cls):
        cursor = cls._db.execute(f"SELECT * FROM {cls._table}")
        return [dict(row) for row in cursor.fetchall()]

    @classmethod
    def where(cls, **conditions):
        where = ' AND '.join(f"{k} = ?" for k in conditions)
        cursor = cls._db.execute(f"SELECT * FROM {cls._table} WHERE {where}", 
                                  tuple(conditions.values()))
        return [dict(row) for row in cursor.fetchall()]

    @classmethod
    def create(cls, **data):
        columns = ', '.join(data.keys())
        placeholders = ', '.join('?' * len(data))
        cursor = cls._db.execute(
            f"INSERT INTO {cls._table} ({columns}) VALUES ({placeholders})",
            tuple(data.values())
        )
        cls._db.commit()
        return cursor.lastrowid

class User(Model):
    _table = 'users'

