import re
from pathlib import Path

def search_files(directory, pattern, content_pattern=None, extensions=None):
    results = []

    for path in Path(directory).rglob('*'):
        if not path.is_file():
            continue

        if extensions and path.suffix not in extensions:
            continue

        if not re.search(pattern, path.name):
            continue

        if content_pattern:
            try:
                content = path.read_text()
                matches = list(re.finditer(content_pattern, content))
                if matches:
                    results.append({
                        'path': str(path),
                        'matches': [(m.start(), m.group()) for m in matches]
                    })
            except:
                continue
        else:
            results.append({'path': str(path)})

    return results

