import asyncio

class EventEmitter:
    def __init__(self):
        self._listeners = defaultdict(list)
        self._once_listeners = defaultdict(list)

    def on(self, event, callback):
        self._listeners[event].append(callback)
        return self

    def once(self, event, callback):
        self._once_listeners[event].append(callback)
        return self

    def off(self, event, callback=None):
        if callback:
            self._listeners[event] = [c for c in self._listeners[event] if c != callback]
        else:
            self._listeners[event] = []
        return self

    def emit(self, event, *args, **kwargs):
        for callback in self._listeners[event]:
            callback(*args, **kwargs)

        for callback in self._once_listeners[event]:
            callback(*args, **kwargs)
        self._once_listeners[event] = []

        return self

emitter = EventEmitter()
emitter.on('data', lambda x: print(f"Received: {x}"))
emitter.emit('data', 'Hello!')"}

