import json

class RedisCache:
    def __init__(self, host='localhost', port=6379, db=0):
        self.client = redis.Redis(host=host, port=port, db=db, decode_responses=True)

    def get(self, key):
        value = self.client.get(key)
        if value:
            try:
                return json.loads(value)
            except:
                return value
        return None

    def set(self, key, value, ttl=None):
