✿ARGS✿: {"path": "./table_fmt.py", "content": "def format_table(data, headers=None):
    if not data:
        return ""

    if headers:
        data = [headers] + data

    col_widths = []
    for col in range(len(data[0])):
        width = max(len(str(row[col])) for row in data)
        col_widths.append(width)

    lines = []
    separator = '+' + '+'.join('-' * (w + 2) for w in col_widths) + '+'

    lines.append(separator)
    for i, row in enumerate(data):
        cells = [f" {str(cell).ljust(col_widths[j])} " for j, cell in enumerate(row)]
        lines.append('|' + '|'.join(cells) + '|')
        if i == 0 and headers:
            lines.append(separator)
    lines.append(separator)

    return '\n'.join(lines)

data = [
    ['Alice', 25, 'Engineer'],
    ['Bob', 30, 'Designer'],
    ['Charlie', 35, 'Manager']
]
print(format_table(data, headers=['Name', 'Age', 'Role']))"}

